SELECT count(*) FROM public.lineitem lineitem WHERE EXISTS (SELECT 1 FROM public.orders o, public.customer c, public.supplier s, public.nation n, public.region r WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND s.s_suppkey = lineitem.l_suppkey AND s.s_nationkey = c.c_nationkey AND n.n_nationkey = s.s_nationkey AND r.r_regionkey = n.n_regionkey AND r.r_name = 'ASIA');
